int receive_and_process_message(struct kiocb *iocb, struct socket *sock,
                                struct msghdr *msg, size_t size,
                                int msg_flags) {
    struct sock *sk = sock->sk;
    int flags = msg_flags;
    int err, copied = 0;
    struct sk_buff *skb;

    if (sk->sk_state == TCP_CLOSE)
        return -ENOTCONN;

    if (sk->sk_err)
        return sock_error(sk);

    while (size) {
        skb = skb_dequeue(&sk->sk_receive_queue);
        if (!skb)
            break;

        if (skb->len <= size)
            copied += skb->len;
        else
            skb = skb_clone(skb, GFP_KERNEL);

        err = skb_copy_datagram_iovec(skb, 0, msg->msg_iov,
                                      min(skb->len, size), msg_flags);
        if (err < 0) {
            kfree_skb(skb);
            return err;
        }

        size -= skb->len;
        kfree_skb(skb);
    }

    if (!copied)
        return -EAGAIN;

    return copied;
}

ssize_t receive_and_process_notification(struct kiocb *iocb, struct socket *sock,
                                        struct msghdr *msg, size_t size,
                                        int msg_flags) {
  ssize_t received = 0;
  struct sk_buff *skb;
  struct sock *sk = sock->sk;
  int err;

  if (sk->sk_shutdown & RCV_SHUTDOWN)
    return 0;

  while ((skb = skb_dequeue(&sk->sk_receive_queue))) {
    if (skb->len > size) {
      msg_flags |= MSG_TRUNC;
      received = size;
    } else {
      received = skb->len;
    }

    err = skb_copy_datagram_iovec(skb, 0, msg->msg_iov, received);
    if (err) {
      kfree_skb(skb);
      return err;
    }

    msg->msg_namelen = sizeof(struct sockaddr_in);
    memcpy(msg->msg_name, skb->cb, sizeof(struct sockaddr_in));

    kfree_skb(skb);
    break;
  }

  return received;
}

int receive_and_process_message(struct kiocb *iocb, struct socket *sock,
                                struct msghdr *msg, size_t size,
                                int msg_flags) {
    struct sock *sk = sock->sk;
    int flags = msg_flags;
    int copied = 0;
    int err = 0;

    if (sk->sk_state == TCP_CLOSE)
        return -ENOTCONN;

    if (flags & MSG_OOB)
        flags |= MSG_DONTWAIT;

    if (flags & MSG_TRUNC)
        flags &= ~MSG_TRUNC;

    while (1) {
        struct sk_buff *skb = skb_dequeue(&sk->sk_receive_queue);
        if (skb) {
            int len = skb->len;

            if (len > size) {
                if (flags & MSG_TRUNC) {
                    copied = len;
                } else {
                    copied = size;
                    err = -EMSGSIZE;
                }
            } else {
                copied = len;
            }

            if (memcpy_to_msg(msg, skb->data, copied)) {
                err = -EFAULT;
            }

            if (iocb && iocb->ki_flags & IOCB_FLAG_WRITE)
                iocb->ki_bytes = copied;

            if (skb->len > copied) {
                skb_pull(skb, copied);
                skb_queue_head(&sk->sk_receive_queue, skb);
            } else {
                kfree_skb(skb);
            }

            break;
        }

        if (flags & MSG_DONTWAIT) {
            return -EAGAIN;
        }

        err = wait_for_queue(sock, &sk->sk_receive_queue, flags & MSG_WAITALL);
        if (err) {
            break;
        }
    }

    return (err == -EAGAIN) ? copied : err;
}

int recv_from_socket(struct kiocb *iocb, struct socket *sock, struct msghdr *msg,
                     size_t size, int msg_flags)
{
    int ret;
    struct sock *sk = sock->sk;
    struct sk_buff *skb;
    struct sockaddr *addr = msg->msg_name;
    int addr_len = msg->msg_namelen;
    int copied = 0;
    int target = size;

    if (msg->msg_flags & MSG_OOB)
        target = 1;

    if (target > USHRT_MAX)
        target = USHRT_MAX;

    skb = skb_recv_datagram(sk, msg_flags, &ret);
    if (!skb)
        return ret;

    copied = skb->len;
    if (copied > target) {
        if (!(msg_flags & MSG_TRUNC))
            copied = target;
        else
            copied = skb->len;
    }

    if (addr && addr_len >= sizeof(sa_family_t)) {
        struct sockaddr_in *sin = (struct sockaddr_in *)addr;

        sin->sin_family = AF_INET;
        sin->sin_addr.s_addr = skb->skb_iif;
        sin->sin_port = htons(ntohs(inet_sk(sk)->sport));
        msg->msg_namelen = sizeof(*sin);
    }

    if (!(msg_flags & MSG_TRUNC))
        ret = skb_copy_datagram_iovec(skb, 0, msg->msg_iov, copied);

    if (ret)
        return ret;

    msg->msg_flags |= MSG_TRUNC;
    sock_recvmsg_end(iocb, sock, msg, copied, ret);
    return copied;
}

ssize_t receive_and_process_message(struct kiocb *iocb, struct socket *sock,
                                    struct msghdr *msg, size_t size,
                                    int msg_flags) {
    struct sock *sk = sock->sk;
    ssize_t ret;
    int flags = msg_flags;
    struct sk_buff *skb;

    if (sk->sk_shutdown & RCV_SHUTDOWN)
        return 0;

    if (flags & MSG_OOB) {
        return -EOPNOTSUPP;
    }

    skb = skb_recv_datagram(sk, flags, &ret);
    if (!skb)
        return ret;

    if (skb->len > size) {
        if (!(flags & MSG_TRUNC))
            ret = size;
        else
            ret = skb->len;
    } else {
        ret = skb->len;
    }

    if (!(flags & MSG_TRUNC)) {
        struct sockaddr_in *sin = (struct sockaddr_in *)&msg->msg_name;
        sin->sin_family = AF_INET;
        sin->sin_addr.s_addr = skb->network_header;
        sin->sin_port = ntohs(skb->protocol);
        msg->msg_namelen = sizeof(*sin);
    }

    if (skb->data_len > 0) {
        ret = skb_copy_datagram_iovec(skb, 0, msg->msg_iov, ret);
        if (ret < 0)
            return ret;
    }

    sock_put(skb->sk);

    return ret;
}
